function minimumDeletions(nums) {
  const n = nums.length;
  let minIndex = 0;
  let maxIndex = 0;

  for (let i = 1; i < n; i++) {
    if (nums[i] < nums[minIndex]) {
      minIndex = i;
    }
    if (nums[i] > nums[maxIndex]) {
      maxIndex = i;
    }
  }

  const left = Math.min(minIndex, maxIndex);
  const right = Math.max(minIndex, maxIndex);

  const frontOnly = right + 1;
  const backOnly = n - left;
  const bothEnds = (left + 1) + (n - right);
  return Math.min(frontOnly, backOnly, bothEnds);
}

