function minimumDeletions(nums) {
  const n = nums.length;
  const lo = nums.indexOf(Math.min(...nums));
  const hi = nums.indexOf(Math.max(...nums));
  let best = Infinity;
  for (let front = 0; front <= n; front++) {
    for (let back = 0; front + back <= n; back++) {
      const gone = i => i < front || i >= n - back;
      if (gone(lo) && gone(hi)) best = Math.min(best, front + back);
    }
  }
  return best;
}

