function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 8);
  const span = size === 'large' ? 100000 : 12;
  const seen = new Set();
  const nums = [];
  while (nums.length < n) {
    const v = Math.floor(rand() * (2 * span + 1)) - span;
    if (seen.has(v)) continue;
    seen.add(v);
    nums.push(v);
  }
  return [nums];
}
